function segmentedUtility(id,intent,context){const value=context.utility?.[id];if(typeof value==='number')return value;const model=context.model??'generic';const task=intent.taskClass??'generic';if(!value)return .5;const pass=value.passRateByModel?.[model]??value.passRateByModel?.generic??.5;const delta=value.qualityDeltaByTaskClass?.[task]??value.qualityDeltaByTaskClass?.generic??0;const token=value.tokenDeltaByModel?.[model]??0;return Math.max(0,Math.min(1,pass+delta-token*.1));}
function providerForTechnique(graph,techniqueId,providers,context){const ids=graph.relations.filter((edge)=>edge.type==='deliveredBy'&&edge.from===techniqueId).map((edge)=>edge.to);const now=context.now?new Date(context.now).getTime():Date.now();return ids.map((id)=>providers.find((p)=>p.providerId===id)).filter(Boolean).filter((p)=>p.status==='stable'&&!p.trust?.blockers?.length&&(!p.validUntil||new Date(p.validUntil).getTime()>now)&&(context.allowExternal!==false||p.sourceId==='forgeos-local')).sort((a,b)=>(b.trust?.score??0)-(a.trust?.score??0)||(a.estimatedTokens??0)-(b.estimatedTokens??0)||a.providerId.localeCompare(b.providerId))[0]??null;}
export function rerankTechniques(graph,candidates,intent,context,providers){const available=new Set(context.tools??[]);const inclusions=[];const exclusions=[];for(const candidate of candidates){const t=candidate.technique;if(candidate.excluded){exclusions.push({id:t.techniqueId,reasons:candidate.reasons});continue;}const missing=(t.requiredTools??[]).filter((tool)=>!available.has(tool));if(missing.length){exclusions.push({id:t.techniqueId,reasons:[`missing-tools:${missing.join(',')}`]});continue;}if(['quarantined','deprecated'].includes(t.maturity)){exclusions.push({id:t.techniqueId,reasons:[`maturity:${t.maturity}`]});continue;}const provider=providerForTechnique(graph,t.techniqueId,providers,context);if(!provider){exclusions.push({id:t.techniqueId,reasons:['no-stable-provider']});continue;}const triggerFit=Math.min(1,Math.max(0,candidate.score/160));const domainFit=(intent.domains??[]).some((domain)=>(t.domains??[]).includes(domain))?1:.4;const toolFit=1;const evidenceFit=(t.produces??[]).length?1:.5;const measuredUtility=segmentedUtility(t.techniqueId,intent,context);const modelCompatibility=(provider.compatibility?.agents??[]).includes(context.agent??'generic')||(provider.compatibility?.agents??[]).includes('*')?1:.6;const freshness=provider.validUntil?Math.max(0,Math.min(1,(new Date(provider.validUntil).getTime()-Date.now())/(30*86400000))):.8;const trust=(provider.trust?.score??0)/100;const tokenPenalty=Math.min(.25,(provider.estimatedTokens??0)/10000);const score=.22*triggerFit+.16*1+.12*domainFit+.10*toolFit+.10*evidenceFit+.10*measuredUtility+.08*modelCompatibility+.07*freshness+.05*trust-tokenPenalty;inclusions.push({id:t.techniqueId,technique:t,provider,score,reasons:[...candidate.reasons,`utility:${measuredUtility.toFixed(2)}`,`provider:${provider.providerId}`,`tokens:${provider.estimatedTokens??0}`],mappedOutcomes:candidate.mappedOutcomes??[]});}return{inclusions:inclusions.sort((a,b)=>b.score-a.score||a.id.localeCompare(b.id)),exclusions:exclusions.sort((a,b)=>a.id.localeCompare(b.id))};}
